import * as anchor from "@anchor-lang/core";
import { getMint } from "@solana/spl-token";

// [DEPENDENCY] Imports Common from target/types/common.ts, generated by anchor build.
import { Common } from "../target/types/common";
// [DEPENDENCY] Imports treasury settings from migrations/devnet.json.
const settings = require("./devnet.json");

/** Initialize the selected devnet treasury once; reruns verify its existing configuration. */
module.exports = async function (provider: anchor.AnchorProvider) {
  const genesis = await provider.connection.getGenesisHash();
  if (genesis !== "EtWTRABZaYq6iMfeYKouRu166VU2xqa1wcaWoxPkrZBG") {
    throw new Error("This setup script only initializes the Common Chain devnet treasury.");
  }
  anchor.setProvider(provider);
  const program = anchor.workspace.common as anchor.Program<Common>;
  if (program.programId.toBase58() !== settings.programId) {
    throw new Error("Anchor program ID does not match migrations/devnet.json.");
  }
  const cmnMint = new anchor.web3.PublicKey(settings.cmnMint);
  const mint = await getMint(provider.connection, cmnMint);
  const minStake = new anchor.BN(settings.stakeCmn).mul(new anchor.BN(10).pow(new anchor.BN(mint.decimals)));
  const treasury = anchor.web3.PublicKey.findProgramAddressSync([Buffer.from("treasury")], program.programId)[0];
  const existing = await program.account.treasury.fetchNullable(treasury);
  if (existing) {
    if (!existing.cmnMint.equals(cmnMint) || !existing.minStake.eq(minStake) ||
        !existing.votingPeriod.eq(new anchor.BN(settings.votingPeriodSeconds)) ||
        existing.quorumPercent !== settings.quorumPercent) {
      throw new Error("Treasury already exists with different settings; no transaction was sent.");
    }
    console.log(`Treasury already initialized: ${treasury.toBase58()}`);
    return;
  }
  const programData = anchor.web3.PublicKey.findProgramAddressSync(
    [program.programId.toBuffer()], new anchor.web3.PublicKey("BPFLoaderUpgradeab1e11111111111111111111111")
  )[0];
  const initialize = program.methods
    .initialize(minStake, new anchor.BN(settings.votingPeriodSeconds), settings.quorumPercent)
    .accountsPartial({ payer: provider.wallet.publicKey, cmnMint, program: program.programId, programData });
  // Preflight the exact setup before broadcasting; failures leave the treasury uninitialized.
  await initialize.simulate();
  console.log(`Initialization signature: ${await initialize.rpc()}`);
};
